import{_ as o,o as t,c as a,ag as r}from"./chunks/framework.44aEvdQQ.js";const d=JSON.parse('{"title":"You Are Going to Make Mistakes","description":"","frontmatter":{"title":"You Are Going to Make Mistakes","order":8},"headers":[],"relativePath":"about/chapters/08-you-are-going-to-make-mistakes.md","filePath":"about/chapters/08-you-are-going-to-make-mistakes.md"}'),n={name:"about/chapters/08-you-are-going-to-make-mistakes.md"};function s(i,e,l,u,m,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h3 id="_08-you-are-going-to-make-mistakes" tabindex="-1">08.<br>You Are Going to Make Mistakes <a class="header-anchor" href="#_08-you-are-going-to-make-mistakes" aria-label="Permalink to &quot;08.&lt;br&gt;You Are Going to Make Mistakes&quot;">​</a></h3><h4 id="safe-failure-develops-irreplaceable-judgment" tabindex="-1">Safe Failure Develops Irreplaceable Judgment <a class="header-anchor" href="#safe-failure-develops-irreplaceable-judgment" aria-label="Permalink to &quot;Safe Failure Develops Irreplaceable Judgment&quot;">​</a></h4><p><a href="https://amycedmondson.com/psychological-safety/" target="_blank" rel="noreferrer">Amy Edmondson</a>, Professor of Leadership at Harvard Business School, defines three types of errors:</p><ol><li>Avoidable mistakes: errors we should not be making and need to immediately avoid making</li><li>Complex mistakes: when life contrives to feel like a &#39;perfect storm&#39; that&#39;s hard to replicate. We learn from these errors by planning for these new edge cases we now know exist</li><li>Intelligent mistakes: &#39;errors&#39; that feel like wins because they evolve our understanding of our work, making us smarter</li></ol><p>Mistakes are not your enemy, you just feel out of control when other people make them. Feeling out of control when your name is above the door is too vulnerable for many owners.</p><blockquote><p>&quot;Change is inevitable; progress is optional&quot;</p><p>— John Maxwell</p></blockquote><p>You are going to make mistakes. <strong>Your employees are going to make mistakes</strong>. You need to be comfortable giving critical feedback when avoidable mistakes are made (they cannot be repeated); you need to be patient when complex errors are made (your team needs your trust to learn); you need to encourage intelligent mistakes (better to learn in the safety of a company that learns than to have intelligent mistakes present as avoidable ones because people were afraid to speak up when they spotted an iceberg)</p><blockquote><p>&quot;The only thing worse than a bad decision is no decision&quot;</p><p>— <em>Theodore Roosevelt</em></p></blockquote><p>Encouraging your team to take action bravely, without having all the information is how people learn. A huge double advantage forms when you trust your people to learn by doing:</p><ol><li>You develop employees&#39; ability to feel a sense of control in their work, that makes them feel valuable and useful. They see themselves as important team players, not just a replaceable body</li><li>Over time you develop a saleable asset — your company is filled with people who can think for themselves without you needing to be the company brain. You document processes and build intellectual property that both alleviates the pressure from your shoulders and, if you choose to sell, creates a more desirable asset to a would-be buyer</li></ol><blockquote><p>&quot;Realising that the individual employees want to do the right thing, but often are forced by the system into the wrong behavior, has profound managerial implications.&quot;</p><p>— <em>Simple_Complexity</em> by William Donaldson</p></blockquote><p>Your people want to be useful, they want to do the right thing. They want to feel a sense of meaning in their lives, to be part of a group that does good work and is always learning. You encourage learning by accepting (most importantly, by communicating to your team that) <strong>mistakes are going to happen</strong>, and that we need to sort which types of mistake we can tolerate and even encourage.</p><blockquote><p>&quot;Learning must take place from the bottom up. You cannot force learning. Your employees have to learn for themselves, and you must provide the environment for them to do so.&quot;</p><p>— <em>Simple_Complexity</em> by William Donaldson</p></blockquote><p>You should want your team to be filled with life-long learners. Start by learning yourself that not all mistakes are bad.</p>',14)])])}const c=o(n,[["render",s]]);export{d as __pageData,c as default};
